<script setup lang="ts">
import { resolvedAppearance } from '../../../shared/appearance.mjs'
definePageMeta({ layout: 'bare' })
const route = useRoute(), api = useApi(), binder = ref<any>(null), error = ref(''), page = ref(0)
onMounted(async () => { try { binder.value = await api('/api/shared/' + route.params.token) } catch (e) { error.value = errorMessage(e) } })
const spread = ref(true)
const pageNumbers = computed(() => binder.value ? Array.from({length: Math.min(spread.value ? 2 : 1, binder.value.page_count - page.value)}, (_, i) => page.value + i) : [])
const appearance = computed(() => resolvedAppearance(binder.value?.appearance, binder.value?.color))
const size = computed(() => binder.value ? binder.value.columns * binder.value.rows : 9)
const slots = computed<Record<number, any>>(() => Object.fromEntries((binder.value?.slots || []).map((s: any) => [s.position, s])))
</script>
<template><header class="shared-header"><NuxtLink to="/" class="brand"><img src="/icon.svg" alt="" /><span>CardShelf</span></NuxtLink><span class="badge">{{ binder?.binder_type === 'tracking' ? 'Read-only tracking checklist' : 'Read-only binder plan' }}</span></header><p v-if="error" class="alert error">{{ error }}</p><div v-else-if="!binder" class="loading-panel">Loading shared binder…</div><div v-else class="shared-content"><header class="page-heading"><div class="binder-title-block"><BinderCover v-if="binder.binder_type !== 'tracking'" :binder="binder" :share-token="String(route.params.token)" class="binder-heading-cover" /><div><span class="eyebrow">SHARED WITH YOU</span><h1>{{ binder.title }}</h1><p>{{ binder.description }}</p></div></div></header><TrackingBinder v-if="binder.binder_type === 'tracking'" :binder="binder" read-only /><template v-else><BinderBook v-model="page" v-model:spread="spread" :pages="binder.page_count"><BinderSurface :class="{ 'single-page': !spread }" :binder="binder" :share-token="String(route.params.token)"><div v-for="p in pageNumbers" :key="p" class="binder-page"><div class="binder-page-heading"><span>PAGE {{ p + 1 }}</span><small>{{ size }} pockets</small></div><div class="pocket-grid" :style="{ gridTemplateColumns: 'repeat(' + binder.columns + ', minmax(0, 1fr))' }"><div v-for="i in size" :key="i" class="pocket" role="img" :aria-label="slots[p * size + i - 1] ? slots[p * size + i - 1].name + ' · ' + slots[p * size + i - 1].label : 'Empty pocket'" :class="{ filled: slots[p * size + i - 1] }"><template v-if="slots[p * size + i - 1]"><CardArtwork :card="slots[p * size + i - 1]" :printing="slots[p * size + i - 1]" :effects-mode="String(appearance.effects_mode)" /><span class="pocket-caption">{{ slots[p * size + i - 1].label }}</span></template><small v-else>Empty pocket</small></div></div></div></BinderSurface></BinderBook><p class="data-note">A planned layout does not establish ownership, condition, availability or a sale offer. Collection quantities and private notes are not shared.</p></template></div></template>

<style scoped>
.shared-content :deep(.binder-stage){grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.shared-content :deep(.binder-stage.single-page){grid-template-columns:minmax(0,1fr)}.shared-content .binder-page{min-width:0}
@media(max-width:600px){.shared-content :deep(.binder-stage){padding:7px;gap:7px}.shared-content .binder-page{padding:6px}.shared-content .pocket-grid{gap:4px}.shared-content .binder-page-heading small{display:none}}
</style>
